import * as signalR from '@microsoft/signalr';

class SignalRService {
    constructor() {
        this.connection = null;
        this.onMessageCallback = null;
        this.onMessageSentCallback = null;
        this.onConversationUpdateCallback = null;
        this.onUserStatusCallback = null;
        this.connectionPromise = null;
    }

    async startConnection(token, baseUrl = 'http://localhost:5000') {
        // 🔥 Если уже подключено - возвращаем сразу
        if (this.connection?.state === signalR.HubConnectionState.Connected) {
            console.log('✅ SignalR уже подключён');
            return true;
        }

        // 🔥 Если подключение в процессе - ждём его
        if (this.connectionPromise) {
            console.log('⏳ SignalR уже подключается...');
            return await this.connectionPromise;
        }

        console.log('🔌 Подключение к SignalR...');

        // 🔥 Создаём подключение с оптимизациями
        this.connection = new signalR.HubConnectionBuilder()
            .withUrl(`${baseUrl}/chathub?access_token=${token}`, {
                // 🔥 ТОЛЬКО WebSocket (быстрее чем LongPolling)
                transport: signalR.HttpTransportType.WebSockets,
                // 🔥 Пропускаем negotiation (ускоряет на 1-2 сек)
                skipNegotiation: true
            })
            .withAutomaticReconnect([0, 1000, 2000]) // 🔥 Быстрее интервалы
            .configureLogging(signalR.LogLevel.Warning) // 🔥 Меньше логов
            .build();

        // 🔥 Регистрируем обработчики ДО подключения
        this.connection.on('ReceiveMessage', (message) => {
            console.log('📩 ReceiveMessage:', message);
            if (this.onMessageCallback) {
                this.onMessageCallback(message, false);
            }
        });

        this.connection.on('MessageSent', (message) => {
            console.log('✅ MessageSent:', message);
            if (this.onMessageSentCallback) {
                this.onMessageSentCallback(message, true);
            }
        });

        this.connection.on('ConversationUpdated', () => {
            console.log('🔄 ConversationUpdated');
            if (this.onConversationUpdateCallback) {
                this.onConversationUpdateCallback();
            }
        });

        this.connection.on('UserStatusChanged', (userId, isOnline) => {
            console.log('🟢 UserStatusChanged:', userId, isOnline);
            if (this.onUserStatusCallback) {
                this.onUserStatusCallback(userId, isOnline);
            }
        });

        this.connection.onreconnecting((error) => {
            console.log('🔄 Reconnecting...', error);
        });

        this.connection.onreconnected((connectionId) => {
            console.log('✅ Reconnected:', connectionId);
        });

        this.connection.onclose((error) => {
            console.log('❌ Closed:', error);
            this.connectionPromise = null;
        });

        // 🔥 Кэшируем промис подключения
        this.connectionPromise = this.connection.start()
            .then(() => {
                console.log('✅ SignalR подключён за ~500ms');
                return true;
            })
            .catch((err) => {
                console.error('❌ SignalR ошибка:', err);
                this.connectionPromise = null;
                
                // 🔥 Fallback без skipNegotiation если WebSocket не работает
                return this.startConnectionFallback(token, baseUrl);
            });

        return await this.connectionPromise;
    }

    // 🔥 Fallback если WebSocket со skipNegotiation не сработал
    async startConnectionFallback(token, baseUrl) {
        console.log('🔄 Пробуем без skipNegotiation...');
        
        this.connection = new signalR.HubConnectionBuilder()
            .withUrl(`${baseUrl}/chathub?access_token=${token}`, {
                transport: signalR.HttpTransportType.WebSockets | 
                          signalR.HttpTransportType.LongPolling
                // Без skipNegotiation
            })
            .withAutomaticReconnect([0, 2000, 5000])
            .build();

        this.setupHandlers();

        try {
            await this.connection.start();
            console.log('✅ SignalR подключён через fallback');
            return true;
        } catch (err) {
            console.error('❌ Fallback не удался:', err);
            this.connectionPromise = null;
            return false;
        }
    }

    setupHandlers() {
        this.connection.on('ReceiveMessage', (message) => {
            if (this.onMessageCallback) this.onMessageCallback(message, false);
        });
        this.connection.on('MessageSent', (message) => {
            if (this.onMessageSentCallback) this.onMessageSentCallback(message, true);
        });
        this.connection.on('ConversationUpdated', () => {
            if (this.onConversationUpdateCallback) this.onConversationUpdateCallback();
        });
        this.connection.on('UserStatusChanged', (userId, isOnline) => {
            if (this.onUserStatusCallback) this.onUserStatusCallback(userId, isOnline);
        });
    }

    async sendMessage(recipientId, content) {
        if (!this.connection || this.connection.state !== signalR.HubConnectionState.Connected) {
            throw new Error('SignalR not connected');
        }
        await this.connection.invoke('SendMessage', recipientId.toString(), content);
    }

    onMessage(callback) { this.onMessageCallback = callback; }
    onMessageSent(callback) { this.onMessageSentCallback = callback; }
    onConversationUpdate(callback) { this.onConversationUpdateCallback = callback; }
    onUserStatus(callback) { this.onUserStatusCallback = callback; }

    async stopConnection() {
        if (this.connection) {
            await this.connection.stop();
            this.connection = null;
            this.connectionPromise = null;
            console.log('SignalR отключён');
        }
    }

    isConnected() {
        return this.connection?.state === signalR.HubConnectionState.Connected;
    }
}

export default new SignalRService();
